def score(program: str) -> float:
    import ast
    try:
        t = ast.parse(program)
    except Exception:
        return 0.0
    n = 0
    names = set()
    for x in ast.walk(t):
        n += 1
        if isinstance(x, ast.Name):
            names.add(x.id)
    return 0.7 * min(1.0, n / 150) + 0.3 * min(len(names), 12) / 12

